import '../value_objects/email_address.dart';

/// The session's user. Equality by id: the same user stays the same after
/// changing their name.
final class User {
  const User({required this.id, required this.name, required this.email});

  /// Opaque, generated by the backend. It is also the identifier the
  /// `AppLogger` receives, never the email.
  final String id;
  final String name;
  final EmailAddress email;

  User rename(String newName) => User(id: id, name: newName, email: email);

  @override
  bool operator ==(Object other) => other is User && other.id == id;

  @override
  int get hashCode => id.hashCode;
}
